require 'spec_helper'

describe "Search Page Parsing" do

  describe "Artworks page" do
    specify "Van Gogh paintings" do
      parser = GoogleSearchPageCrawler.new
      result = JSON.parse(parser.crawl(fixture_file_path("van-gogh-artworks.html")))
      expected_artworks = JSON.parse(load_fixture_file("van-gogh-expected-parse-response.json"))["artworks"]

      expect(result["artworks"].size).to eq(47)
      expect(result["artworks"].map { |a| a["name"] }).to eq(expected_artworks.map { |a| a["name"] })
      expect(result["artworks"].map { |a| a["link"] }).to eq(expected_artworks.map { |a| a["link"] })
      expect(result["artworks"].map { |a| a["image"].to_s }).to eq(expected_artworks.map { |a| a["image"].to_s })

      expect(result["artworks"].map { |a| a["extensions"] }).to eq(expected_artworks.map { |a| a["extensions"] })
    end

    specify "Leonardo da Vinci paintings" do
      parser = GoogleSearchPageCrawler.new
      result = JSON.parse(parser.crawl(fixture_file_path("leonardo-da-vinci-artworks.html")))

      expect(result["artworks"].size).to eq(47)
      expect(result["artworks"][0]["name"]).to eq("Salvator Mundi")
      expect(result["artworks"][0]["extensions"]).to eq(["1500"])
      expect(result["artworks"][0]["link"]).to eq("https://www.google.com/search?sa=X&sca_esv=952fdb03796c5895&biw=1279&bih=882&sxsrf=AE3TifPJ8-DKZ8r4YpfqqRZuarBsnfwd2w:1755194365892&q=Salvator+Mundi&stick=H4sIAAAAAAAAAONgFuLQz9U3MMlJN1PiArEy0nPTzPO0lLKTrfTLMotLE3PiE4tKkJiZxSVW5flF2cWLWPmCE3PKEkvyixR8S_NSMgGqq00fTQAAAA&ved=2ahUKEwjHkMPF8IqPAxUAJrkGHUQ-BnUQtq8DegQIHxAD")
      expect(result["artworks"][0]["image"]).to eq("data:image/jpeg;base64,")
    end

    specify "Monet paintings" do
      parser = GoogleSearchPageCrawler.new
      result = JSON.parse(parser.crawl(fixture_file_path("monet-artworks.html")))

      expect(result["artworks"].size).to eq(50)
      expect(result["artworks"][0]["name"]).to eq("Impression, Sunrise")
      expect(result["artworks"][0]["extensions"]).to eq(["1872"])
      expect(result["artworks"][0]["link"]).to eq("https://www.google.com/search?sa=X&sca_esv=952fdb03796c5895&biw=1279&bih=882&sxsrf=AE3TifM_5ohXuFfUgED1fT58PY9Djs6sjA:1755194880310&q=Impression,+Sunrise&stick=H4sIAAAAAAAAAONgFuLQz9U3MKzIy1LiBLPiK4yMtZSyk630yzKLSxNz4hOLSpCYmcUlVuX5RdnFi1iFPXMLilKLizPz83QUgkvzijKLUwGEYmULUQAAAA&ved=2ahUKEwiD2ui68oqPAxW3pZUCHdE4DEAQtq8DegQIMRAD")
    end
  end
end